"""Command-line parsing compatible with the observed command interface."""
import sys
import os
import re
import pwd
from model import VERSION,COLUMNS,resource

# Each entry is a long spelling, a canonical action and its argument convention.
OPTIONS=[('no-color','C',0),('no-colour','C',0),('delay','d',1),('filter','F',1),
 ('help','h',0),('highlight-changes','H',2),('no-mouse','M',0),('max-iterations','n',1),
 ('pid','p',1),('readonly','readonly',0),('sort-key','s',1),('tree','t',0),
 ('user','u',2),('no-unicode','U',0),('version','V',0),('no-meters','no-meters',0),
 ('no-functionbar','no-functionbar',0),('no-function-bar','no-functionbar',0)]
SHORT={action:mode for _,action,mode in OPTIONS if len(action)==1}

class Exit(Exception):
    def __init__(self,code=0):self.code=code

def error(s):
    sys.stderr.write(s+'\n')
    raise Exit(1)


def numeric(s,what):
    m=re.match(r'\s*[+-]?\d+',s)
    if not m:error(f'Error: invalid {what} "{s}".')
    v=int(m[0])
    # Parsing is by the native signed integer conversion; very large values
    # saturate before being used by the option-specific bounds check.
    return max(-(2**63),min(2**63-1,v))


def user_number(s):
    if s is None:return os.getuid()
    try:return pwd.getpwnam(s).pw_uid
    except (KeyError,ValueError,OverflowError):pass
    if re.fullmatch(r'\s*\+?\d+',s):
        n=int(s)
        if n<2**32-1:return n
    error(f'Error: invalid user "{s}".')


def parse(argv=None):
    if argv is None:argv=sys.argv[1:]
    result={};positionals=[];i=0;prog=sys.argv[0]
    def apply(action,value):
        if action=='h':
            sys.stdout.write(resource('cli_help.txt'));raise Exit()
        if action=='V':
            print('htop '+VERSION);raise Exit()
        if action=='s':
            if value=='help':sys.stdout.write(resource('columns.txt'));raise Exit()
            if value not in COLUMNS:error(f'Error: invalid column "{value}".')
            result['sort']=value
        elif action=='d':result['delay']=max(1,min(100,numeric(value,'delay value')))
        elif action=='H':
            result['highlight_changes']=1
            if value is not None:result['highlight_changes_delay_secs']=max(1,min(86400,numeric(value,'highlight delay value')))
        elif action=='n':
            n=numeric(value,'maximum iteration count')
            if n<=0 and n!=-(2**63):error('Error: maximum iteration count must be positive.')
            result['iterations']=n if n>0 else 2**63
        elif action=='u':result['uid']=user_number(value)
        elif action=='p':
            pids=result.setdefault('pids',set())
            for s in value.split(','):
                m=re.match(r'\s*[+-]?\d+',s);pids.add(int(m[0]) if m else 0)
        elif action=='F':result['filter']=value
        elif action=='C':result['monochrome']=True
        elif action=='t':result['tree']=True
        elif action=='M':result['enable_mouse']=0
        elif action=='U':result['ascii']=True
        elif action=='readonly':result['readonly']=True
        elif action=='no-meters':result['no_meters']=True
        elif action=='no-functionbar':result['hide_function_bar']=2
    while i<len(argv):
        arg=argv[i];i+=1
        if arg=='--':positionals.extend(argv[i:]);break
        if not arg.startswith('-') or arg=='-':
            positionals.append(arg)
            if 'POSIXLY_CORRECT' in os.environ:positionals.extend(argv[i:]);break
            continue
        if arg.startswith('--'):
            name,has_eq,val=arg[2:].partition('=')
            matches=[o for o in OPTIONS if o[0]==name]
            if not matches:matches=[o for o in OPTIONS if o[0].startswith(name)]
            if not matches:error(f"{prog}: unrecognized option '{arg}'")
            unique=[]
            for o in matches:
                if (o[1],o[2]) not in [(u[1],u[2]) for u in unique]:unique.append(o)
            if len(unique)>1:
                # GNU's ambiguity report preserves the option table order.
                report_order=['no-color','no-mouse','no-unicode','no-meters','no-functionbar','no-function-bar']
                display=[o[0] for o in matches if o[0]!='no-colour']
                if all(n in report_order for n in display):display.sort(key=report_order.index)
                error(f"{prog}: option '--{name}' is ambiguous; possibilities:"+''.join(" '--"+n+"'" for n in display))
            longname,action,mode=matches[0]
            if has_eq and mode==0:error(f"{prog}: option '--{name}' doesn't allow an argument")
            value=val if has_eq else None
            if mode==1 and value is None:
                if i>=len(argv):error(f"{prog}: option '--{name}' requires an argument")
                value=argv[i];i+=1
            elif mode==2 and value is None and i<len(argv) and not argv[i].startswith('-'):
                value=argv[i];i+=1
            apply(action,value)
        else:
            j=1
            while j<len(arg):
                action=arg[j];j+=1
                if action not in SHORT:error(f"{prog}: invalid option -- '{action}'")
                mode=SHORT[action];value=None
                if mode:
                    if j<len(arg):value=arg[j:];j=len(arg)
                    elif mode==1:
                        if i>=len(argv):error(f"{prog}: option requires an argument -- '{action}'")
                        value=argv[i];i+=1
                    elif i<len(argv) and not argv[i].startswith('-'):
                        value=argv[i];i+=1
                apply(action,value)
    if positionals:error('Error: unsupported non-option ARGV-elements: '+' '.join(positionals))
    return result
