import sys
import os
from cli import parse, Exit
from model import Settings


def main():
    try:opts=parse()
    except Exit as e:return e.code
    settings=Settings(opts)
    term=os.environ.get('TERM') or 'unknown'
    import curses
    try:curses.setupterm(term=term)
    except curses.error:
        sys.stderr.write(f'Error opening terminal: {term}.\n')
        return 1
    from ui import run, dumb_output
    if term=='dumb' and not os.isatty(0):
        dumb_output(settings,opts)
        settings.save()
        return 0
    try:
        clean_exit=run(settings,opts)
    except KeyboardInterrupt:return 0
    if clean_exit:settings.save()
    return 0

if __name__=='__main__':
    sys.exit(main())
