        for row,item in enumerate(items[off:off+height]):
            selected=row+off==idx
            role=('select' if focused else 'unfocus') if selected else 'normal'
            self.put(y+row+1,x,item,role,width)
            if not selected and item.startswith('['):
                end=item.find(']')
