def read_key(win):
    try:k=win.get_wch()
    except curses.error:return None
    if isinstance(k,str):
        simple={'\n':'ENTER','\r':'ENTER','\t':'TAB','\x1b':'ESC','\x7f':'BACKSPACE','\b':'BACKSPACE'}
        return simple.get(k,k)
    keys={curses.KEY_UP:'UP',curses.KEY_DOWN:'DOWN',curses.KEY_LEFT:'LEFT',curses.KEY_RIGHT:'RIGHT',
          curses.KEY_HOME:'HOME',curses.KEY_END:'END',curses.KEY_PPAGE:'PAGEUP',curses.KEY_NPAGE:'PAGEDOWN',
          curses.KEY_BACKSPACE:'BACKSPACE',curses.KEY_DC:'DELETE',curses.KEY_BTAB:'BTAB',curses.KEY_ENTER:'ENTER',
          curses.KEY_RESIZE:'RESIZE',curses.KEY_MOUSE:'MOUSE'}
    for i in range(1,13):keys[curses.KEY_F0+i]=f'F{i}'
    keys[curses.KEY_F0+15]='S-F3'
    return keys.get(k,'UNKNOWN')


def run(settings,opts):
    try:locale.setlocale(locale.LC_ALL,'')
    except locale.Error:pass
    try:curses.set_escdelay(25)
    except AttributeError:os.environ['ESCDELAY']='25'
    scr=curses.initscr()
    clean_exit=False
    def stop(signum,frame):raise KeyboardInterrupt()
    oldsig={}
    for sig in (signal.SIGTERM,signal.SIGHUP):oldsig[sig]=signal.signal(sig,stop)
    try:
        if opts.get('iterations'):
            # Leave the alternate screen immediately for a finite snapshot run.
            seq=curses.tigetstr('rmcup')
            if seq:sys.stdout.buffer.write(seq+b'\x1b[H\x1b[2J');sys.stdout.flush()
        try:curses.noecho();curses.cbreak()
        except curses.error:pass
        scr.keypad(True);scr.timeout(100)
        app=Interface(scr,settings,opts)
        app.draw();app.count=1
        if opts.get('iterations')==1:return True
        while not app.quit:
            k=read_key(scr)
            now=time.monotonic();redraw=False
            if k is not None:app.key(k);redraw=True
            elif not os.isatty(0):break
            if app.quit:break
            if now>=app.next_update:
                if not app.paused and app.mode not in ('help','info','menu'):
                    app.sample.update();app.refresh_list()
                app.next_update=now+app.v['delay']/10;app.count+=1;redraw=True
            if redraw:app.draw()
            if opts.get('iterations') and app.count>=opts['iterations']:break
        clean_exit=app.clean_exit
    except KeyboardInterrupt:clean_exit=False
    finally:
        try:curses.curs_set(1);curses.mousemask(0);curses.nocbreak();scr.keypad(False);curses.echo();curses.endwin()
        except curses.error:
            try:curses.endwin()
            except curses.error:pass
        if opts.get('iterations'):
            h,w=scr.getmaxyx();sys.stdout.write(f'\x1b[{h};1H');sys.stdout.flush()
        for sig,handler in oldsig.items():signal.signal(sig,handler)
    return clean_exit
