            self.menu_items=['Reset on fork: off','Other','FiFo','RoundRobin','Batch','Idle']
            self.menu_index=1
        elif kind=='policy_priority':
            self.menu_title='Priority:';self.menu_width=15;self.menu_verb='Set';self.menu_items=[str(i) for i in range(1,100)]

    def menu_screen(self,y):
        self.table(y,self.menu_width+1,False)
        self.menu_offset=self.panel(y,0,self.menu_width,self.menu_title,self.menu_items,self.menu_index,self.menu_offset,True)
        self.footer([('Enter',self.menu_verb),('Esc','Cancel')],pad=7)

    def get_targets(self):
        if self.tagged:return set(self.tagged)
        if self.chosen:return {self.chosen['PID']}
        return set()

    def menu_apply(self):
        idx=self.menu_index;kind=self.menu
        if kind=='sort':
            self.s['sort_key']=self.menu_items[idx];self.s['sort_direction']=sort_direction(self.s['sort_key']);self.s['tree_view']=0
            self.set_changed();self.sel=0;self.scroll=0
        elif kind=='user':
            self.uid=None if idx==0 else next((uid for uid,name in self.sample.uid_names.items() if name==self.menu_items[idx]),None)
            self.sel=0;self.scroll=0
        elif kind=='signal':
            n=self.signals[idx][0]
            if n:
                for pid in self.get_targets():
                    try:os.kill(pid,n)
                    except OSError:self.beep()
        elif kind=='affinity':
            if self.affinity:
                for pid in self.get_targets():
                    try:os.sched_setaffinity(pid,self.affinity)
                    except OSError:self.beep()
        elif kind=='io':
            if idx==0:val=0
            elif idx<=8:val=(1<<13)+(idx-1)
            elif idx<=16:val=(2<<13)+(idx-9)
            else:val=3<<13
            try:
                import ctypes
                libc=ctypes.CDLL(None,use_errno=True)
                for pid in self.get_targets():
                    if libc.syscall(251,1,pid,val)<0:self.beep()
            except Exception:self.beep()
        elif kind=='policy':
            if idx==0:
                self.policy_reset=not self.policy_reset;self.menu_items[0]='Reset on fork: '+('on' if self.policy_reset else 'off');return
            policy=[0,0,1,2,3,5][idx]
            if policy in (1,2):
                self.pending_policy=policy;self.open_menu('policy_priority');return
            for pid in self.get_targets():
                try:os.sched_setscheduler(pid,policy|(getattr(os,'SCHED_RESET_ON_FORK',0) if self.policy_reset else 0),os.sched_param(0))
                except OSError:self.beep()
        elif kind=='policy_priority':
            for pid in self.get_targets():
                try:os.sched_setscheduler(pid,self.pending_policy,os.sched_param(idx+1))
                except OSError:self.beep()
        self.mode='main';self.refresh_list()

    def open_info(self,kind):
        if not self.visible:return
        self.chosen=self.visible[self.sel].copy();self.info_kind=kind;self.mode='info'
        self.info_offset=0;self.info_index=0;self.info_filter='';self.info_x=0;self.trace_stop=False
        self.load_info()

    def load_info(self):
        p=self.chosen;pid=p['PID'];path=f'/proc/{pid}';kind=self.info_kind
        prefixes={'command':'Command of process ','env':'Environment of process ','files':'Snapshot of files open in process ','locks':'Locks of process ','trace':'Trace of process '}
        self.info_title=prefixes[kind]+str(pid)+' - '+p['rawcmd'];self.info_subtitle=''
        if kind=='command':self.info=[p['rawcmd']]
        elif kind=='env':
            try:env=open(path+'/environ','rb').read().split(b'\0');self.info=sorted(e.decode(errors='replace') for e in env if e)
            except OSError:self.info=['Could not read environment.']
        elif kind=='files':
            self.info_subtitle='   FD TYPE    MODE DEVICE           SIZE     OFFSET       NODE  NAME'
            self.info=["Could not execute 'lsof'. Please make sure it is available in your $PATH."]
        elif kind=='locks':
            self.info_subtitle='   FD TYPE       EXCLUSION  READ/WRITE DEVICE       NODE               START                 END  FILE'
            self.info=['No locks have been found for the selected process.']
        elif kind=='trace':self.info=["Could not execute 'strace'. Please make sure it is available in your $PATH."]

    def info_lines(self):
        lines=self.info[:]
        if self.info_kind=='command':
            lines=[]
            for line in self.info[0].splitlines() or ['']:
                lines+=textwrap.wrap(line,max(1,self.w),replace_whitespace=False,drop_whitespace=False) or ['']
        if self.info_filter:lines=[l for l in lines if any(f.lower() in l.lower() for f in self.info_filter.split('|'))]
        return lines

    def info_screen(self):
        title=self.info_title
        # Very long command lines in the caption end with an ellipsis.
        if len(title)>self.w:title=title[:max(0,self.w-3)]+'...'
        self.raw(0,0,title,'title')
        if self.info_subtitle:self.put(1,0,self.info_subtitle,'header',self.w)
        lines=self.info_lines()
        height=self.h-3
        self.info_offset=max(0,min(self.info_offset,max(0,len(lines)-height)))
        for i,line in enumerate(lines[self.info_offset:self.info_offset+height]):
            self.put(2+i,0,line[self.info_x:],'normal')
        if not self.prompt:
            items=[('F3','Search'),('F4','FILTER' if self.info_filter else 'Filter')]
            if self.info_kind=='trace':items += [('F8','AutoScroll'),('F9','Resume Tracing' if self.trace_stop else 'Stop Tracing')]
            else:items += [('F5','Refresh')]
            items += [('Esc','Done')]
            self.footer(items,pad=7)

    def draw_prompt(self):
        if self.prompt=='filter':
            prefix='EnterDone  EscClear    Filter: '
            self.put(self.h-1,0,'','select',self.w)
            self.put(self.h-1,0,'Enter');self.put(self.h-1,5,'Done  ','select')
            self.put(self.h-1,11,'Esc');self.put(self.h-1,14,'Clear    Filter: ','select')
        else:
            prefix='F3Next  S-F3Prev   EscCancel    Search: '
            self.put(self.h-1,0,'','select',self.w)
            self.put(self.h-1,0,'F3');self.put(self.h-1,2,'Next  ','select')
            self.put(self.h-1,8,'S-F3');self.put(self.h-1,12,'Prev   ','select')
            self.put(self.h-1,19,'Esc');self.put(self.h-1,22,'Cancel    Search: ','select')
        found=True
        if self.prompt=='search' and self.prompt_text:
            things=[self.command(p) for p in self.visible] if self.mode=='main' else self.info_lines()
            found=any(self.prompt_text.lower() in s.lower() for s in things)
        self.put(self.h-1,len(prefix),self.prompt_text,'select' if found else 'red')
        self.cursor=(self.h-1,min(self.w-1,len(prefix)+self.prompt_cursor))

    def draw(self):
        self.h,self.w=self.win.getmaxyx();self.cursor=None
        self.win.erase();self.footer_hits=[]
        if self.mode=='help':self.help_screen()
        elif self.mode=='info':self.info_screen()
        else:
            y=self.header()
            if self.mode=='setup':self.setup_screen(y)
            elif self.mode=='menu':self.menu_screen(y)
            else:
                self.table(y)
                if self.has_footer() and not (self.opts.get('iterations')==1 and self.count==0):self.main_footer()
        if self.prompt:self.draw_prompt()
        try:
            if self.cursor:curses.curs_set(1);self.win.move(*self.cursor)
            else:curses.curs_set(0);self.win.move(self.h-1,0)
        except curses.error:pass
        self.win.refresh()

    def beep(self):
        try:curses.beep()
        except curses.error:pass

    def prompt_start(self,kind,initial=None):
        self.prompt=kind
        self.prompt_text=(self.filter if self.mode=='main' else self.info_filter) if kind=='filter' else ''
        if initial is not None:self.prompt_text=initial
        self.prompt_cursor=len(self.prompt_text)
        if initial:self.prompt_update()

    def prompt_update(self):
        if self.prompt=='filter':
            if self.mode=='main':self.filter=self.prompt_text;self.refresh_list();self.sel=min(self.sel,max(0,len(self.visible)-1))
            else:self.info_filter=self.prompt_text;self.info_offset=0
        else:self.search_match(0)

    def search_match(self,step=0):
        if not self.prompt_text:return
        data=[self.command(p) for p in self.visible] if self.mode=='main' else self.info_lines()
        if not data:return
        idx=self.sel if self.mode=='main' else self.info_index
        idx=(idx+step)%len(data)
        for i in range(len(data)):
            j=(idx+i*(1 if step>=0 else -1))%len(data)
            if self.prompt_text.lower() in data[j].lower():
                if self.mode=='main':self.sel=j
                else:self.info_index=j;self.info_offset=max(0,j-(self.h-4)//2)
                return

    def prompt_key(self,k):
        if k in ('ESC','ENTER'):
            if k=='ESC' and self.prompt=='filter':self.prompt_text='';self.prompt_update()
            self.prompt=None;return
        if k in ('F3','S-F3') and self.prompt=='search':self.search_match(1 if k=='F3' else -1);return
        if k=='BACKSPACE':
            if self.prompt_cursor:self.prompt_text=self.prompt_text[:self.prompt_cursor-1]+self.prompt_text[self.prompt_cursor:];self.prompt_cursor-=1
        elif k=='DELETE':self.prompt_text=self.prompt_text[:self.prompt_cursor]+self.prompt_text[self.prompt_cursor+1:]
        elif k=='LEFT':self.prompt_cursor=max(0,self.prompt_cursor-1)
        elif k=='RIGHT':self.prompt_cursor=min(len(self.prompt_text),self.prompt_cursor+1)
        elif k in ('HOME','\x01'):self.prompt_cursor=0
        elif k in ('END','\x05'):self.prompt_cursor=len(self.prompt_text)
        elif k in ('\x15','\x17'):self.prompt_text='';self.prompt_cursor=0
        elif len(k)==1 and k.isprintable():
            self.prompt_text=self.prompt_text[:self.prompt_cursor]+k+self.prompt_text[self.prompt_cursor:];self.prompt_cursor+=1
        self.prompt_update()

    def move_selection(self,k,idx,n,page):
        if k=='UP':idx-=1
        elif k=='DOWN':idx+=1
        elif k=='PAGEUP':idx-=max(1,page)
        elif k=='PAGEDOWN':idx+=max(1,page)
        elif k=='HOME':idx=0
        elif k=='END':idx=n-1
        return max(0,min(idx,n-1))

    def setup_key(self,k):
        if self.rename:
            if k=='ENTER':
                if self.editname:self.s['name']=self.editname;self.set_changed()
                self.rename=False
            elif k=='ESC':self.rename=False
            elif k=='BACKSPACE':self.editname=self.editname[:-1]
            elif k in ('\x15','\x17'):self.editname=''
            elif len(k)==1 and k.isprintable():self.editname+=k
            return
        if k in ('ESC','F10','q'):
            self.mode='main';self.moving=False;self.refresh_list();self.palette();self.set_mouse();return
        maxfocus=1 if self.cat in (0,1,4) else len(self.settings.layout_widths())+1 if self.cat==2 else 3
        if self.moving and self.cat==2 and self.focus and self.focus<maxfocus:
            ms=self.settings.meters[self.focus-1];idx=self.index()
            if k in ('UP','DOWN') and ms:
                j=max(0,min(len(ms)-1,idx+(1 if k=='DOWN' else -1)))
                ms[idx],ms[j]=ms[j],ms[idx];self.set_index(j);self.set_changed();return
            if k in ('LEFT','RIGHT') and ms:
                target=max(0,min(maxfocus-2,self.focus-1+(1 if k=='RIGHT' else -1)))
                if target!=self.focus-1:
                    m=ms.pop(idx);self.settings.meters[target].append(m);self.focus=target+1;self.set_index(len(self.settings.meters[target])-1);self.set_changed()
                return
        if k in ('LEFT','RIGHT','TAB','BTAB'):
            if k in ('RIGHT','TAB'):self.focus=(self.focus+1)%(maxfocus+1)
            else:self.focus=max(0,self.focus-1) if k=='LEFT' else (self.focus-1)%(maxfocus+1)
            return
        if k in ('UP','DOWN','HOME','END','PAGEUP','PAGEDOWN'):
            n=len(self.setup_items(self.focus));idx=self.move_selection(k,self.index(),n,max(1,self.h-self.body_y-3) if hasattr(self,'body_y') else 15)
            self.set_index(idx);return
        if not self.focus:
            if k=='ENTER':self.focus=1;return
            if len(k)==1:
                for i,name in enumerate(self.setup_items(0)):
                    if name.lower().startswith(k.lower()):self.cat=i;break
            return
        idx=self.index()
        if self.cat==0:
            key,label=DISPLAY_OPTIONS[idx]
            if key and k in (' ','ENTER','F7','F8','+','-','[',']'):
                val=self.setting(key)
                if key in ('delay','highlight_changes_delay_secs','hide_function_bar'):
                    delta=-1 if k in ('F7','-','[') else 1
                    val=max(1 if key!='hide_function_bar' else 0,min(255 if key=='delay' else 2 if key=='hide_function_bar' else 86400,val+delta))
                else:val=1-bool(val)
                if key in self.s:self.s[key]=int(val)
                else:self.v[key]=int(val)
                if key=='enable_mouse':self.set_mouse()
                if key=='all_branches_collapsed':
                    self.collapsed={p['PID'] for p in self.sample.processes} if val else set()
                self.set_changed();self.refresh_list()
        elif self.cat==1 and k in (' ','ENTER'):
            self.settings.layout=LAYOUTS[idx][0];n=len(LAYOUTS[idx][2])
            while len(self.settings.meters)<n:self.settings.meters.append([])
            if len(self.settings.meters)>n:
                for ms in self.settings.meters[n:]:self.settings.meters[n-1].extend(ms)
                self.settings.meters=self.settings.meters[:n]
            self.set_changed()
        elif self.cat==4 and k in (' ','ENTER'):
            self.v['color_scheme']=idx;self.set_changed();self.palette()
        elif self.cat==2:
            n=len(self.settings.layout_widths())
            if self.focus==n+1:
                if k in ('ENTER','F5',' '):
                    m=METERS[idx];target=n-1;self.settings.meters[target].append((m[0],m[3]));self.focus=target+1;self.set_index(len(self.settings.meters[target])-1);self.moving=True;self.set_changed()
            else:
                ms=self.settings.meters[self.focus-1]
                if not ms:return
                if k=='ENTER':self.moving=not self.moving
                elif k in (' ','F4','t'):
                    m,style=ms[idx]
                    styles=[1,2,3,4]
                    if m in ('Clock','Date','DateTime','Uptime','Hostname'):styles=[2,4]
                    if m=='Blank':styles=[2]
                    style=styles[(styles.index(style)+1)%len(styles)] if style in styles else styles[0]
                    ms[idx]=(m,style);self.set_changed()
                elif k in ('DELETE','F9'):
                    ms.pop(idx);self.set_index(min(idx,len(ms)-1));self.set_changed()
        elif self.cat==3:
            if self.focus==1:
                if k=='F2':self.rename=True;self.editname=self.s['name']
                elif k=='F5':
                    self.settings.screens.append(new_screen('New screen',MAIN_FIELDS));self.tab=len(self.settings.screens)-1;self.rename=True;self.editname='';self.set_changed()
                elif k in ('DELETE','F9') and len(self.settings.screens)>1:
                    self.settings.screens.pop(self.tab);self.tab=min(self.tab,len(self.settings.screens)-1);self.set_changed()
                elif k in ('F7','F8'):
                    j=max(0,min(len(self.settings.screens)-1,self.tab+(-1 if k=='F7' else 1)))
                    self.settings.screens[self.tab],self.settings.screens[j]=self.settings.screens[j],self.settings.screens[self.tab];self.tab=j;self.set_changed()
            elif self.focus==2:
                fs=self.s['fields']
                if k in ('DELETE','F9') and len(fs)>1:fs.pop(idx);self.set_index(min(idx,len(fs)-1));self.set_changed()
                elif k in ('F7','F8'):
                    j=max(0,min(len(fs)-1,idx+(-1 if k=='F7' else 1)));fs[idx],fs[j]=fs[j],fs[idx];self.set_index(j);self.set_changed()
            elif self.focus==3 and k in ('F5','ENTER',' '):
                fs=self.s['fields'];dest=self.index(2);fs.insert(dest,COLUMNS[idx]);self.indices[(3,2)]=dest+1;self.set_changed()

    def menu_key(self,k):
        if k in ('ESC','F10','q'):
            self.mode='main';self.refresh_list();return
        if k=='ENTER':self.menu_apply();return
        if k==' ' and self.menu=='affinity':
            i=self.menu_index
            if i in self.affinity:self.affinity.remove(i)
            else:self.affinity.add(i)
            self.menu_items[i]=f'[{"x" if i in self.affinity else " "}] CPU {i}';return
        if k in ('UP','DOWN','HOME','END','PAGEUP','PAGEDOWN'):
            self.menu_index=self.move_selection(k,self.menu_index,len(self.menu_items),self.h-self.body_y-2);return
        if len(k)==1 and k.isprintable():
            now=time.monotonic()
            if now-self.menu_time>1:self.menu_query=''
            self.menu_query+=k;self.menu_time=now
            for i,entry in enumerate(self.menu_items):
                if entry.lstrip().lower().startswith(self.menu_query.lower()):self.menu_index=i;return
            self.menu_query=k
            for i,entry in enumerate(self.menu_items):
                if entry.lstrip().lower().startswith(k.lower()):self.menu_index=i;return

    def info_key(self,k):
        if k in ('ESC','F10','q','ENTER'):
            self.mode='main';self.refresh_list();return
        if k in ('F3','/'):self.prompt_start('search');return
        if k in ('F4','\\'):self.prompt_start('filter');return
        if k=='F5':self.load_info();return
        if k=='F9' and self.info_kind=='trace':self.trace_stop=not self.trace_stop;return
        if k in ('UP','DOWN','HOME','END','PAGEUP','PAGEDOWN'):
            self.info_offset=self.move_selection(k,self.info_offset,len(self.info_lines()),self.h-3)
        elif k=='LEFT':self.info_x=max(0,self.info_x-5)
        elif k=='RIGHT':self.info_x+=5
        elif k in ('^','\x01'):self.info_x=0

    def main_key(self,k):
        if k in ('q','F10'):self.quit=True;return
        if k in ('F1','h','?'):self.mode='help';return
        if k in ('F2','C','S'):
            self.mode='setup';self.cat=0;self.focus=0;self.moving=False;self.indices={};self.offsets={};return
        if k in ('F3','/'):self.prompt_start('search');return
        if k in ('F4','\\'):self.prompt_start('filter');return
        if k in ('F6','>','<','.'):self.open_menu('sort');return
        if k=='u':self.open_menu('user');return
        if k in ('F9','k') and not self.readonly:
            if self.visible:self.open_menu('signal')
            return
        if k in ('a','i','Y') and not self.readonly:
            if self.visible:self.open_menu({'a':'affinity','i':'io','Y':'policy'}[k])
            return
        if k in ('e','w','l','x','s'):
            self.open_info({'e':'env','w':'command','l':'files','x':'locks','s':'trace'}[k]);return
        if k in ('UP','DOWN','HOME','END','PAGEUP','PAGEDOWN'):
            self.sel=self.move_selection(k,self.sel,len(self.visible),getattr(self,'table_height',15));self.follow=None;return
        if k=='LEFT':self.hscroll=max(0,self.hscroll-5);return
        if k=='RIGHT':self.hscroll+=5;return
        if k in ('^','\x01'):self.hscroll=0;return
        if k in ('$','\x05'):
            if self.visible:self.hscroll=max(0,sum(len(self.cell(self.visible[self.sel],f)) for f in self.s['fields'])-self.w)
            return
        if k in ('TAB','BTAB'):
            self.tab=(self.tab+(1 if k=='TAB' else -1))%len(self.settings.screens);self.sel=0;self.scroll=0;self.hscroll=0;self.refresh_list();return
        if k in ('F5','t'):
            self.s['tree_view']=1-self.s['tree_view'];self.set_changed();self.refresh_list();return
        if k in ('N','M','P','T'):
            col={'N':'PID','M':'PERCENT_MEM','P':'PERCENT_CPU','T':'TIME'}[k]
            pre='tree_' if self.s['tree_view'] else ''
            self.s[pre+'sort_key']=col;self.s[pre+'sort_direction']=sort_direction(col);self.set_changed();self.refresh_list();return
        if k=='I':
            prop='tree_sort_direction' if self.s['tree_view'] else 'sort_direction';self.s[prop]*=-1;self.set_changed();self.refresh_list();return
        if k in ('H','K','O','p','m'):
            prop={'H':'hide_userland_threads','K':'hide_kernel_threads','O':'hide_running_in_container','p':'show_program_path','m':'show_merged_command'}[k]
            self.v[prop]=1-self.v[prop];self.set_changed();self.refresh_list();return
        if k=='#':self.no_meters=not self.no_meters;return
        if k=='Z':self.paused=not self.paused;return
        if k=='F':
            if self.visible:self.follow=self.visible[self.sel]['PID']
            return
        if k in ('+','-','*'):
            if self.s['tree_view']:
                if k=='*':
                    if self.collapsed:self.collapsed=set()
                    else:self.collapsed={p['PID'] for p in self.visible if p['PPID'] not in {q['PID'] for q in self.visible}}
                elif self.visible:
                    pid=self.visible[self.sel]['PID']
                    if k=='+':self.collapsed.discard(pid)
                    else:self.collapsed.add(pid)
                self.refresh_list()
            return
        if k in (' ','c'):
            if not self.visible:return
            p=self.visible[self.sel];pid=p['PID']
            if k==' ':
                if pid in self.tagged:self.tagged.remove(pid)
                else:self.tagged.add(pid)
                self.sel=min(self.sel+1,len(self.visible)-1)
            else:
                targets={pid}
                while True:
                    more={p['PID'] for p in self.sample.processes if p['PPID'] in targets or p['TGID'] in targets}
                    more-=targets
                    if not more:break
                    targets|=more
                self.tagged|=targets
            return
        if k=='U':self.tagged=set();return
        if k in ('F7','F8',']','[','{','}'):
            if self.readonly:return
            delta=-1 if k in ('F7',']','}') else 1
            self.chosen=self.visible[self.sel] if self.visible else None
            for pid in self.get_targets():
                try:
                    if k in ('{','}'):
                        p=next((p for p in self.sample.processes if p['PID']==pid),None)
                        if p:
                            with open(f'/proc/{pid}/autogroup','w') as f:f.write(str(p['AUTOGROUP_NICE']+delta))
                    else:os.setpriority(os.PRIO_PROCESS,pid,os.getpriority(os.PRIO_PROCESS,pid)+delta)
                except OSError:self.beep()
            return
        if k=='ESC':
            if self.v['hide_function_bar']==1:self.hide_bar=True
            return
        if k.isdigit():
            now=time.monotonic()
            if now-self.last_pid_time>1:self.last_pid_keys=''
            self.last_pid_keys+=k;self.last_pid_time=now
            matches=[(i,p) for i,p in enumerate(self.visible) if str(p['PID']).startswith(self.last_pid_keys)]
            if matches:self.sel=matches[0][0]
            return
        if len(k)==1 and k.isprintable():self.prompt_start('search',k)

    def mouse(self):
        try:_,x,y,_,state=curses.getmouse()
        except curses.error:return
        if state & getattr(curses,'BUTTON4_PRESSED',0):self.key('UP');self.key('UP');self.key('UP');return
        if state & getattr(curses,'BUTTON5_PRESSED',0):self.key('DOWN');self.key('DOWN');self.key('DOWN');return
