        if self.mode=='setup':
            base=self.header()
            if y>base and y<self.h-1:
                self.focus=0 if x<17 else (x-17)//21+1 if self.cat in (2,3) else 1
                idx=y-base-1+(self.offsets.get((self.cat,self.focus),0) if self.focus else 0)
                self.set_index(idx)
                if self.cat in (0,1,4) and self.focus:self.setup_key(' ')
            return
        if self.mode=='menu' and x<=self.menu_width:
            if y>self.body_y:self.menu_index=max(0,min(len(self.menu_items)-1,y-self.body_y-1+self.menu_offset))
            if state&curses.BUTTON1_DOUBLE_CLICKED:self.menu_apply()
            return
        if self.mode=='main':
