                        key='tree_sort_key' if self.s['tree_view'] else 'sort_key';dr='tree_sort_direction' if self.s['tree_view'] else 'sort_direction'
                        if self.s[key]==c:self.s[dr]*=-1
                        else:self.s[key]=c;self.s[dr]=sort_direction(c)
                        self.set_changed();self.refresh_list();return
            elif y>self.body_y:self.sel=max(0,min(len(self.visible)-1,self.scroll+y-self.body_y-1))
            elif self.v['screen_tabs'] and y==self.body_y-1:
