    def key(self,k):
        if k=='RESIZE':return
        if k=='MOUSE':self.mouse();return
        if k=='\x03':self.quit=True;self.clean_exit=False;return
        if k=='\x0c':self.win.clearok(True);return
        if self.prompt:self.prompt_key(k);return
        if self.mode=='help':self.mode='main';return
        if self.mode=='setup':self.setup_key(k);return
        if self.mode=='menu':self.menu_key(k);return
        if self.mode=='info':self.info_key(k);return
